create extension if not exists pgcrypto;
create table public.profiles (id uuid primary key references auth.users(id) on delete cascade,email text,display_name text,role text not null default 'user' check(role in ('user','admin')),created_at timestamptz not null default now());
create table public.prompts (id uuid primary key default gen_random_uuid(),title text not null,prompt text not null,image_url text not null,category text not null,tags text[] not null default '{}',copy_count integer not null default 0 check(copy_count>=0),like_count integer not null default 0 check(like_count>=0),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),published boolean not null default true,author_id uuid references auth.users(id) on delete set null);
create table public.prompt_likes (id uuid primary key default gen_random_uuid(),prompt_id uuid not null references public.prompts(id) on delete cascade,user_id uuid not null references auth.users(id) on delete cascade,created_at timestamptz not null default now(),unique(prompt_id,user_id));
create index prompts_published_created_idx on public.prompts(published,created_at desc);create index prompts_category_idx on public.prompts(category);create index prompt_likes_prompt_idx on public.prompt_likes(prompt_id);
create or replace function public.is_admin() returns boolean language sql stable security definer set search_path=public as $$select exists(select 1 from profiles where id=auth.uid() and role='admin')$$;
create or replace function public.update_timestamp() returns trigger language plpgsql as $$begin new.updated_at=now();return new;end$$;create trigger prompts_timestamp before update on public.prompts for each row execute function public.update_timestamp();
create or replace function public.increment_copy_count(prompt_id uuid) returns void language plpgsql security definer set search_path=public as $$begin update prompts set copy_count=copy_count+1 where id=prompt_id and published=true;end$$;
create or replace function public.increment_like_count(prompt_id uuid) returns void language plpgsql security definer set search_path=public as $$begin update prompts set like_count=like_count+1 where id=prompt_id;end$$;
create or replace function public.sync_like_count() returns trigger language plpgsql security definer set search_path=public as $$begin if tg_op='INSERT' then update prompts set like_count=like_count+1 where id=new.prompt_id;return new;else update prompts set like_count=greatest(0,like_count-1) where id=old.prompt_id;return old;end if;end$$;create trigger likes_count after insert or delete on public.prompt_likes for each row execute function public.sync_like_count();
create or replace view public.trending_prompts with (security_invoker=true) as select p.*, (p.copy_count*3+p.like_count*2+greatest(0,30-extract(day from now()-p.created_at)))::numeric as trending_score from public.prompts p;
alter table public.profiles enable row level security;alter table public.prompts enable row level security;alter table public.prompt_likes enable row level security;
create policy "public reads published prompts" on public.prompts for select using(published or is_admin());create policy "admins manage prompts" on public.prompts for all to authenticated using(is_admin()) with check(is_admin());create policy "profiles readable" on public.profiles for select using(true);create policy "users update own profile" on public.profiles for update to authenticated using(id=auth.uid()) with check(id=auth.uid());create policy "users read own likes" on public.prompt_likes for select to authenticated using(user_id=auth.uid());create policy "users create own likes" on public.prompt_likes for insert to authenticated with check(user_id=auth.uid());create policy "users delete own likes" on public.prompt_likes for delete to authenticated using(user_id=auth.uid());
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('prompt-images','prompt-images',true,10485760,array['image/jpeg','image/png','image/webp']) on conflict(id) do nothing;
create policy "public reads prompt images" on storage.objects for select using(bucket_id='prompt-images');create policy "admins upload prompt images" on storage.objects for insert to authenticated with check(bucket_id='prompt-images' and is_admin());create policy "admins delete prompt images" on storage.objects for delete to authenticated using(bucket_id='prompt-images' and is_admin());
